UPDATE catalogs SET data=(SELECT json_group_array(json(CASE WHEN json_extract(m.value,'$.image')='assets/model-4.png' THEN json_set(m.value,'$.image','assets/model-4-v2.png','$.size',json('[1796,1230]'),'$.view',json('[0,0,1796,1230]'),'$.parts',json((SELECT json_group_array(json(CASE WHEN json_type(p.value,'$.locations')='array' THEN json_set(p.value,'$.x',MAX(0,json_extract(p.value,'$.x')-14),'$.y',MAX(0,json_extract(p.value,'$.y')-18),'$.locations',json((SELECT json_group_array(json(json_set(l.value,'$.x',MAX(0,json_extract(l.value,'$.x')-14),'$.y',MAX(0,json_extract(l.value,'$.y')-18)))) FROM json_each(p.value,'$.locations') l))) ELSE json_set(p.value,'$.x',MAX(0,json_extract(p.value,'$.x')-14),'$.y',MAX(0,json_extract(p.value,'$.y')-18)) END)) FROM json_each(m.value,'$.parts') p))) ELSE m.value END)) FROM json_each(catalogs.data) m),revision=revision+1 WHERE id='main' AND EXISTS (SELECT 1 FROM json_each(catalogs.data) WHERE json_extract(value,'$.image')='assets/model-4.png');
